from ansible.plugins.action.validate_argument_spec import ActionModule

class _Templar:
    def __init__(self):
        self.seen = None

    def template(self, data):
        self.seen = dict(data)
        return {'name': 'alice', 'count': 3}

action = object.__new__(ActionModule)
action._templar = _Templar()

argument_spec = {
    'name': {'type': 'str'},
    'count': {'type': 'int'},
    'missing': {'type': 'str'},
}
task_vars = {
    'name': '{{ user }}',
    'count': '{{ n }}',
    'unrelated': 'ignored',
}

result = action.get_args_from_task_vars(argument_spec, task_vars)

assert result == {'name': 'alice', 'count': 3}
assert action._templar.seen == {'name': '{{ user }}', 'count': '{{ n }}'}
